   ============================================================ */
.msg-translation-detached { display: none !important; }
.msg-translation-wrapper { position: relative !important; margin: 0 !important; padding: 0 !important; }
.msg-translation-btn {
  position: relative !important; color: transparent !important; background: transparent !important;
  border: none !important; font-size: 0 !important; line-height: 0 !important; padding: 0 !important;
  margin: 0 !important; height: 0 !important; min-height: 0 !important; max-height: 0 !important;
  cursor: pointer !important; overflow: visible !important;
}
